// One sheet row per term: this week's average interest and top rising query.
// Terms that failed arrive as error records (not charged); they are logged as rows too.
const rows = [];
const week = new Date().toISOString().slice(0, 10);
for (const { json: item } of $input.all()) {
  if (item.type === 'result') {
    const averages = item.interestOverTime?.averages ?? {};
    for (const term of item.searchTerms) {
      const rising = item.relatedQueries?.[term]?.rising ?? [];
      rows.push({ json: {
        week, term, geo: item.geo || 'worldwide', dates: item.timeRangeResolved,
        avg_interest: averages[term] ?? null,
        top_rising_query: rising[0]?.query ?? '', top_rising_change: rising[0]?.formattedValue ?? '',
        status: 'ok', explore_url: item.exploreUrl,
      } });
    }
  } else if (item.type === 'error') {
    rows.push({ json: {
      week, term: item.searchTerm, geo: item.geo || 'worldwide', dates: '', avg_interest: null,
      top_rising_query: '', top_rising_change: '', status: `error: ${item.error_code}`, explore_url: '',
    } });
  }
}
return rows;
